module Top;
    string a, b, t;
    int i;
    initial begin
        a = "x"; b = "y"; i = 1;
        t = i > 0 ? a : b;
        $display("%s", t);
    end
endmodule

class Item;
    string label;
endclass
module Top;
    Item item;
    initial begin
        item = new;
        $sformat(item.label, "L%0d", 9);
        $display("%s", item.label);
    end
endmodule

module Top;
    bit [8*4-1:0] format;
    string s;
    initial begin
        format = "%0d";
        s = $sformatf(format, 42);
        $display("%s", s);
    end
endmodule

class Log;
    string lines[$];
endclass
module Top;
    string m[string];
    Log log;
    initial begin
        log = new;
        m["k"] = "v";
        log.lines.push_back("x");
        $display("%s %s", m["k"], log.lines[0]);
    end
endmodule
